package com.yuegang.zhihui.wallet.application;import com.yuegang.zhihui.wallet.api.WalletTransactionView;import java.time.ZoneOffset;import java.util.List;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class WalletQueryService{private final JdbcTemplate jdbc;public WalletQueryService(DataSource d){jdbc=new JdbcTemplate(d);}public List<WalletTransactionView>list(long user,int limit){return jdbc.query("SELECT id,type,status,amount,currency,reference_id,created_at FROM wallet_transaction WHERE user_id=? ORDER BY created_at DESC LIMIT ?",(r,n)->new WalletTransactionView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getString(6),r.getTimestamp(7).toLocalDateTime().atOffset(ZoneOffset.UTC)),user,Math.max(1,Math.min(limit,100)));}}
